package com.vidyavedika.auth.security;
import io.jsonwebtoken.*; import io.jsonwebtoken.security.Keys; import java.nio.charset.StandardCharsets; import java.time.Instant; import java.util.Date; import javax.crypto.SecretKey; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service;
@Service public class JwtService { private final SecretKey key; private final long expiry; public JwtService(@Value("${jwt.secret}") String secret,@Value("${jwt.expiry-ms:3600000}") long expiry){this.key=Keys.hmacShaKeyFor(secret.getBytes(StandardCharsets.UTF_8));this.expiry=expiry;} public String generate(Long id,String email,String role){Instant now=Instant.now(); return Jwts.builder().subject(email).claim("userId",id).claim("role",role).issuedAt(Date.from(now)).expiration(Date.from(now.plusMillis(expiry))).signWith(key).compact();} }
